for (unsigned int i = 0; i < max_iter; ++i) {
    c = (a + b) / 2.0;

    // Check if we've reached the desired precision
    if (std::abs(b - a) < precision) {
        break;
    }

    // Check if c is the root
    if (std::abs(f(c)) < precision) {
        break;
    }

    // Determine which subinterval contains the root
    if (f(c) * f(a) < 0) {
        b = c;
    } else {
        a = c;
    }
}

return c;

